  void push(Tel t){lat[gi]=Float.isNaN(t.gLat)?0:lim(t.gLat,-2,2);lng[gi]=Float.isNaN(t.gLong)?0:lim(t.gLong,-2,2);vrt[gi]=Float.isNaN(t.gVert)?0:lim(t.gVert,-2,2);gi=(gi+1)%lat.length;if(!Float.isNaN(t.x)&&!Float.isNaN(t.y)&&(tc==0||Math.abs(t.x-tx[(tc-1)%tx.length])>1||Math.abs(t.y-ty[(tc-1)%ty.length])>1)){tx[tc%tx.length]=t.x;ty[tc%ty.length]=t.y;tc++;}}
  void clearTrace(){tc=0;invalidate();}
  protected void onDraw(Canvas c){scale=getWidth()/430f;c.save();c.scale(scale,scale);draw(c,430,getHeight()/scale);c.restore();}
