  void speedo(Canvas c,float cx,float cy,float rad){p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(cx,cy,rad,Color.rgb(6,12,20),Color.rgb(0,2,7),Shader.TileMode.CLAMP));c.drawCircle(cx,cy,rad,p);p.setShader(null);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(Color.argb(180,150,170,190));c.drawCircle(cx,cy,rad-5,p);c.drawCircle(cx,cy,rad-22,p);float start=205,sweep=130;for(int i=0;i<=120;i++){float q=i/120f;float a=(float)Math.toRadians(start+sweep*q);int spd=Math.round(240*q);boolean major=spd%20==0;boolean mid=spd%10==0;float r1=rad-(major?28:(mid?22:15)),r2=rad-7;p.setStrokeWidth(major?2.8f:(mid?1.8f:1f));p.setColor(spd<50?Color.rgb(15,220,80):spd<150?Color.WHITE:spd<200?Color.rgb(255,160,35):Color.rgb(255,35,45));c.drawLine(cx+(float)Math.cos(a)*r1,cy+(float)Math.sin(a)*r1,cx+(float)Math.cos(a)*r2,cy+(float)Math.sin(a)*r2,p);if(major){txt(c,""+spd,cx+(float)Math.cos(a)*(rad-52),cy+5+(float)Math.sin(a)*(rad-52),11,Color.WHITE,1,Paint.Align.CENTER);}}
   float q=lim(tel.speed/240f,0,1),a=(float)Math.toRadians(start+sweep*q);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);p.setColor(Color.argb(220,230,235,255));c.drawLine(cx,cy,cx+(float)Math.cos(a)*(rad-48),cy+(float)Math.sin(a)*(rad-48),p);p.setStrokeWidth(2);p.setColor(Color.rgb(255,35,45));c.drawLine(cx,cy,cx+(float)Math.cos(a)*(rad-62),cy+(float)Math.sin(a)*(rad-62),p);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(12,14,22));c.drawCircle(cx,cy,12,p);p.setColor(Color.WHITE);c.drawCircle(cx,cy,4,p);
   p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(1,8,15));c.drawCircle(cx,cy,64,p);txt(c,""+tel.speed,cx,cy+4,48,Color.WHITE,1,Paint.Align.CENTER);txt(c,"km/h",cx,cy+28,9,Color.WHITE,0,Paint.Align.CENTER);round(c,cx-26,cy+44,52,44,8,Color.rgb(4,12,20),Color.argb(190,120,140,160));txt(c,tel.gear,cx,cy+72,24,Color.WHITE,1,Paint.Align.CENTER);txt(c,"MT",cx,cy+87,9,Color.WHITE,0,Paint.Align.CENTER);txt(c,"RPM "+tel.rpm,cx,cy+113,9,Color.rgb(180,200,210),0,Paint.Align.CENTER);txt(c,"FUEL "+(tel.fuel>=0?Math.round(tel.fuel)+"%":"--"),cx,cy+127,9,Color.rgb(180,200,210),0,Paint.Align.CENTER);} 
  void drawPanel(Canvas c,int i){float x=gx[i],y=gy[i],w=gw[i],h=closed[i]?34:gh[i];round(c,x,y,w,h,8,Color.rgb(1,15,26),edit&&i==sel?Color.rgb(0,160,255):Color.argb(95,60,140,210));if(edit&&i==sel)handles(c,x,y,w,h);txt(c,closed[i]?"+":"-",x+15,y+20,14,Color.WHITE,1,Paint.Align.CENTER);txt(c,title[i],x+34,y+22,12,Color.WHITE,1,Paint.Align.LEFT);txt(c,"...",x+w-20,y+21,16,Color.rgb(255,55,80),1,Paint.Align.CENTER);if(!closed[i]){if(i==0)chart(c,x+18,y+34,w-36,h-56);else if(i==5)tires(c,x,y,w,h);else if(i==6)map(c,x+14,y+40,w-28,h-54);else fields(c,i,x,y,w,h);}}
  void chart(Canvas c,float x,float y,float w,float h){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(Color.argb(65,100,150,180));c.drawRect(x,y,x+w,y+h,p);for(int j=0;j<5;j++)c.drawLine(x,y+j*h/4,x+w,y+j*h/4,p);line(c,lat,x,y,w,h,Color.rgb(0,230,50));line(c,lng,x,y,w,h,Color.rgb(255,40,50));line(c,vrt,x,y,w,h,Color.rgb(0,140,255));txt(c,"LAT",x+w-88,y+12,8,Color.rgb(0,230,50),1,Paint.Align.LEFT);txt(c,"LONG",x+w-58,y+12,8,Color.rgb(255,40,50),1,Paint.Align.LEFT);txt(c,"VERT",x+w-20,y+12,8,Color.rgb(0,140,255),1,Paint.Align.RIGHT);}
  void line(Canvas c,float[] ar,float x,float y,float w,float h,int col){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.6f);p.setColor(col);Path path=new Path();for(int i=0;i<ar.length;i++){int k=(gi+i)%ar.length;float xx=x+i*w/(ar.length-1),yy=y+h/2-ar[k]*h/4;if(i==0)path.moveTo(xx,yy);else path.lineTo(xx,yy);}c.drawPath(path,p);} 
  void map(Canvas c,float x,float y,float w,float h){round(c,x,y,w,h,6,Color.rgb(0,7,13),Color.argb(70,80,160,220));txt(c,tel.track,x+8,y+15,10,Color.WHITE,1,Paint.Align.LEFT);txt(c,"pontos: "+Math.min(tc,tx.length),x+w-8,y+15,8,Color.rgb(140,180,200),0,Paint.Align.RIGHT);if(tc<2){txt(c,"Ande uma volta para gravar o tracado X/Y",x+w/2,y+h/2,8,Color.rgb(150,180,200),0,Paint.Align.CENTER);return;}float minx=999999,maxx=-999999,miny=999999,maxy=-999999;int n=Math.min(tc,tx.length);for(int i=0;i<n;i++){float xx=tx[i],yy=ty[i];if(xx<minx)minx=xx;if(xx>maxx)maxx=xx;if(yy<miny)miny=yy;if(yy>maxy)maxy=yy;}float sx=(w-24)/Math.max(1,maxx-minx),sy=(h-34)/Math.max(1,maxy-miny);Path path=new Path();for(int i=0;i<n;i++){float px=x+12+(tx[i]-minx)*sx,py=y+24+(ty[i]-miny)*sy;if(i==0)path.moveTo(px,py);else path.lineTo(px,py);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(Color.rgb(0,210,255));c.drawPath(path,p);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(255,50,70));float cx=x+12+(tel.x-minx)*sx,cy=y+24+(tel.y-miny)*sy;c.drawCircle(cx,cy,4,p);} 
  void fields(Canvas c,int i,float x,float y,float w,float h){String[][] d=data(i);float yy=y+58;for(String[] row:d){txt(c,row[0],x+16,yy,10,Color.rgb(170,210,235),0,Paint.Align.LEFT);txt(c,row[1],x+w-18,yy,12,row[2].equals("g")?Color.rgb(0,230,80):Color.WHITE,0,Paint.Align.RIGHT);yy+=20;}}
  String[][] data(int i){if(i==1)return rows("SPEED",tel.speed+" km/h","RPM",tel.rpm+" rpm","THROTTLE",tel.thr+" %","BRAKE",tel.brk+" %","FUEL",one(tel.fuelL)+" L","OIL TEMP",deg(tel.oil),"WATER TEMP",deg(tel.water),"STEER",ang(tel.steer));if(i==2)return rows("TIME",tel.last,"LAP",""+tel.laps,"S1","--","S2","--","S3","--","SPD MAX","--");if(i==3)return rows("TIME",tel.best,"LAP","--","S1","--","S2","--","S3","--","SPD MAX","--");if(i==4)return rows("TIME",tel.total,"LAPS",""+tel.laps,"FUEL",""+(tel.fuel>=0?Math.round(tel.fuel)+"%":"--"));if(i==7)return rows("BOOST",boost(tel.turbo),"POWER",one(tel.power)+" hp","TORQUE",one(tel.torque)+" Nm","RPM",tel.rpm+"");return rows("SESSION","--","SAVED","--");}
  String[][] rows(String...v){String[][] rr=new String[v.length/2][3];for(int i=0;i<v.length;i+=2){rr[i/2][0]=v[i];rr[i/2][1]=v[i+1];rr[i/2][2]=v[i+1].contains("1:")?"g":"";}return rr;}
