  void nav(Canvas c,float w,float h){float y=h-62;round(c,6,y,418,56,10,Color.rgb(2,12,22),Color.argb(70,90,150,190));txt(c,"DASHBOARD",70,y+36,9,Color.rgb(255,55,80),1,Paint.Align.CENTER);txt(c,"MAP",180,y+36,9,Color.WHITE,0,Paint.Align.CENTER);txt(c,"SESSIONS",286,y+36,9,Color.WHITE,0,Paint.Align.CENTER);txt(c,"SETTINGS",380,y+36,9,Color.WHITE,0,Paint.Align.CENTER);} 
